const reqs=[
["audit",()=>tools.read_yui({path:"nl0/references/audit-a.md",start:1,end:250})],
["self",()=>tools.read_yui({path:"nl0/references/self-containment.md",start:1,end:250})],
["external",()=>tools.read_yui({path:"nl0/references/external-theorems.md",start:1,end:250})],
["overview",()=>tools.read_task_input({id:"global-overview.json",pointer:""})],
["sigroot",()=>tools.read_task_input({id:"signature-evidence.json",pointer:""})],
["specroot",()=>tools.read_task_input({id:"spec.json",pointer:""})],
["selection",()=>tools.read_task_input({id:"target-selection.json",pointer:""})]
];
await Promise.allSettled(reqs.map(async([k,f])=>{const r=await f(); store(k,JSON.parse(r)); if(k==="overview") {const v=JSON.parse(r).value;text({key:k,keys:Object.keys(v),hypotheses:v.spec_hypotheses,definitions:v.definitions});} else text({key:k,result:r});}));

